1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8" />
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
6	  <title>MHOBG Studio — Digital Craft. Islamic Values. Global Impact.</title>
7	  <meta name="description" content="MHOBG Studio is a full-stack software development studio building modern web apps, AI tools, Islamic digital solutions, and accessibility platforms." />
8	  <meta name="keywords" content="MHOBG Studio, Heavenly_Dev, web development, AI, Islamic apps, software, Ghana, KNUST" />
9	  <meta name="author" content="Abdul Rahman Mohammed" />
10	  <link rel="icon" href="data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22><text y=%22.9em%22 font-size=%2290%22>🛠️</text></svg>">
11	
12	  <link rel="preconnect" href="https://fonts.googleapis.com" />
13	  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
14	  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet" />
15	  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" crossorigin="anonymous" referrerpolicy="no-referrer" />
16	
17	  <style>
18	    /* ===== RESET & BASE ===== */
19	    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
20	    :root {
21	      --bg: #0a0a0f;
22	      --bg-card: #12121a;
23	      --bg-card-hover: #1a1a2e;
24	      --surface: #181825;
25	      --border: #1e1e32;
26	      --text: #e2e2f0;
27	      --text-muted: #8888a0;
28	      --accent: #7c5cfc;
29	      --accent-glow: rgba(124, 92, 252, 0.25);
30	      --accent2: #3b82f6;
31	      --accent3: #06b6d4;
32	      --gold: #f59e0b;
33	      --success: #22c55e;
34	      --radius: 16px;
35	      --radius-sm: 10px;
36	      --font: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
37	      --mono: 'JetBrains Mono', monospace;
38	      --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
39	    }
40	    html { scroll-behavior: smooth; }
41	    body {
42	      font-family: var(--font);
43	      background: var(--bg);
44	      color: var(--text);
45	      line-height: 1.6;
46	      overflow-x: hidden;
47	      -webkit-font-smoothing: antialiased;
48	    }
49	    a { color: var(--accent); text-decoration: none; transition: var(--transition); }
50	    a:hover { color: #a78bfa; }
51	    img { max-width: 100%; display: block; }
52	    ul { list-style: none; }
53	    ::selection { background: var(--accent); color: #fff; }
54	
55	    /* ===== SCROLLBAR ===== */
56	    ::-webkit-scrollbar { width: 6px; }
57	    ::-webkit-scrollbar-track { background: var(--bg); }
58	    ::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }
59	    ::-webkit-scrollbar-thumb:hover { background: var(--accent); }
60	
61	    /* ===== ANIMATED BG ===== */
62	    #particles-canvas {
63	      position: fixed;
64	      top: 0; left: 0;
65	      width: 100vw; height: 100vh;
66	      z-index: 0;
67	      pointer-events: none;
68	    }
69	
70	    /* ===== NAV ===== */
71	    nav {
72	      position: fixed;
73	      top: 0; left: 0; right: 0;
74	      z-index: 1000;
75	      padding: 0 2rem;
76	      height: 68px;
77	      display: flex;
78	      align-items: center;
79	      justify-content: space-between;
80	      backdrop-filter: blur(20px) saturate(1.5);
81	      -webkit-backdrop-filter: blur(20px) saturate(1.5);
82	      background: rgba(10, 10, 15, 0.75);
83	      border-bottom: 1px solid rgba(255,255,255,0.04);
84	      transition: var(--transition);
85	    }
86	    nav.scrolled { background: rgba(10, 10, 15, 0.92); }
87	    .nav-logo {
88	      display: flex;
89	      align-items: center;
90	      gap: 10px;
91	      font-weight: 800;
92	      font-size: 1.2rem;
93	      letter-spacing: -0.5px;
94	    }
95	    .nav-logo .logo-icon {
96	      width: 36px; height: 36px;
97	      background: linear-gradient(135deg, var(--accent), var(--accent3));
98	      border-radius: 10px;
99	      display: flex;
100	      align-items: center;
101	      justify-content: center;
102	      font-size: 1rem;
103	      color: #fff;
104	    }
105	    .nav-links { display: flex; gap: 2rem; align-items: center; }
106	    .nav-links a {
107	      color: var(--text-muted);
108	      font-size: 0.875rem;
109	      font-weight: 500;
110	      position: relative;
111	      padding: 0.25rem 0;
112	    }
113	    .nav-links a::after {
114	      content: '';
115	      position: absolute;
116	      bottom: -2px; left: 0;
117	      width: 0; height: 2px;
118	      background: var(--accent);
119	      transition: var(--transition);
120	    }
121	    .nav-links a:hover { color: var(--text); }
122	    .nav-links a:hover::after { width: 100%; }
123	    .nav-cta {
124	      background: linear-gradient(135deg, var(--accent), var(--accent2));
125	      color: #fff !important;
126	      padding: 0.5rem 1.25rem;
127	      border-radius: 8px;
128	      font-weight: 600;
129	    }
130	    .nav-cta::after { display: none !important; }
131	    .nav-cta:hover { transform: translateY(-1px); box-shadow: 0 4px 20px var(--accent-glow); }
132	
133	    .hamburger { display: none; flex-direction: column; gap: 5px; cursor: pointer; background: none; border: none; padding: 4px; }
134	    .hamburger span { display: block; width: 24px; height: 2px; background: var(--text); border-radius: 2px; transition: var(--transition); }
135	
136	    /* ===== SECTIONS ===== */
137	    section { position: relative; z-index: 1; }
138	    .section-container {
139	      max-width: 1200px;
140	      margin: 0 auto;
141	      padding: 6rem 2rem;
142	    }
143	    .section-tag {
144	      display: inline-flex;
145	      align-items: center;
146	      gap: 6px;
147	      padding: 0.35rem 1rem;
148	      background: rgba(124, 92, 252, 0.1);
149	      border: 1px solid rgba(124, 92, 252, 0.2);
150	      border-radius: 100px;
151	      font-size: 0.75rem;
152	      font-weight: 600;
153	      color: var(--accent);
154	      text-transform: uppercase;
155	      letter-spacing: 1.5px;
156	      margin-bottom: 1rem;
157	    }
158	    .section-title {
159	      font-size: clamp(2rem, 4vw, 3rem);
160	      font-weight: 800;
161	      letter-spacing: -1px;
162	      line-height: 1.15;
163	      margin-bottom: 1rem;
164	    }
165	    .section-sub {
166	      color: var(--text-muted);
167	      font-size: 1.05rem;
168	      max-width: 600px;
169	      line-height: 1.7;
170	    }
171	
172	    /* ===== HERO ===== */
173	    .hero {
174	      min-height: 100vh;
175	      display: flex;
176	      align-items: center;
177	      justify-content: center;
178	      text-align: center;
179	      padding: 2rem;
180	      position: relative;
181	    }
182	    .hero-content { max-width: 900px; position: relative; z-index: 2; }
183	    .hero-badge {
184	      display: inline-flex;
185	      align-items: center;
186	      gap: 8px;
187	      padding: 0.4rem 1.2rem;
188	      background: rgba(124, 92, 252, 0.08);
189	      border: 1px solid rgba(124, 92, 252, 0.15);
190	      border-radius: 100px;
191	      font-size: 0.8rem;
192	      color: var(--accent);
193	      margin-bottom: 1.5rem;
194	      font-weight: 500;
195	    }
196	    .hero-badge .dot {
197	      width: 6px; height: 6px;
198	      background: var(--success);
199	      border-radius: 50%;
200	      animation: pulse-dot 2s infinite;
201	    }
202	    @keyframes pulse-dot { 0%,100% { opacity: 1; } 50% { opacity: 0.3; } }
203	    .hero h1 {
204	      font-size: clamp(2.5rem, 6vw, 4.5rem);
205	      font-weight: 900;
206	      letter-spacing: -2px;
207	      line-height: 1.05;
208	      margin-bottom: 1.25rem;
209	    }
210	    .hero h1 .gradient {
211	      background: linear-gradient(135deg, var(--accent), var(--accent3), var(--accent2));
212	      -webkit-background-clip: text;
213	      -webkit-text-fill-color: transparent;
214	      background-clip: text;
215	    }
216	    .hero p {
217	      font-size: clamp(1rem, 2vw, 1.2rem);
218	      color: var(--text-muted);
219	      max-width: 640px;
220	      margin: 0 auto 2rem;
221	      line-height: 1.7;
222	    }
223	    .hero-actions {
224	      display: flex;
225	      gap: 1rem;
226	      justify-content: center;
227	      flex-wrap: wrap;
228	    }
229	    .btn {
230	      display: inline-flex;
231	      align-items: center;
232	      gap: 8px;
233	      padding: 0.85rem 2rem;
234	      border-radius: 10px;
235	      font-weight: 600;
236	      font-size: 0.95rem;
237	      border: none;
238	      cursor: pointer;
239	      transition: var(--transition);
240	    }
241	    .btn-primary {
242	      background: linear-gradient(135deg, var(--accent), var(--accent2));
243	      color: #fff;
244	    }
245	    .btn-primary:hover {
246	      transform: translateY(-2px);
247	      box-shadow: 0 8px 30px var(--accent-glow);
248	    }
249	    .btn-secondary {
250	      background: rgba(255,255,255,0.04);
251	      color: var(--text);
252	      border: 1px solid var(--border);
253	    }
254	    .btn-secondary:hover { background: rgba(255,255,255,0.08); transform: translateY(-2px); }
255	    .hero-stats {
256	      display: flex;
257	      justify-content: center;
258	      gap: 3rem;
259	      margin-top: 3rem;
260	      flex-wrap: wrap;
261	    }
262	    .hero-stat { text-align: center; }
263	    .hero-stat .num {
264	      font-size: 2rem;
265	      font-weight: 800;
266	      background: linear-gradient(135deg, var(--text), var(--accent3));
267	      -webkit-background-clip: text;
268	      -webkit-text-fill-color: transparent;
269	      background-clip: text;
270	    }
271	    .hero-stat .label { font-size: 0.8rem; color: var(--text-muted); margin-top: 0.15rem; }
272	
273	    /* ===== ABOUT ===== */
274	    .about-grid {
275	      display: grid;
276	      grid-template-columns: 1fr 1fr;
277	      gap: 4rem;
278	      align-items: center;
279	    }
280	    .about-text h3 {
281	      font-size: 1.5rem;
282	      font-weight: 700;
283	      margin-bottom: 1rem;
284	    }
285	    .about-text p { color: var(--text-muted); margin-bottom: 1rem; line-height: 1.7; }
286	    .about-text .highlight { color: var(--accent); font-weight: 600; }
287	    .about-info-grid {
288	      display: grid;
289	      grid-template-columns: 1fr 1fr;
290	      gap: 1rem;
291	      margin-top: 1.5rem;
292	    }
293	    .about-info-item {
294	      display: flex;
295	      align-items: center;
296	      gap: 10px;
297	      padding: 0.75rem;
298	      background: var(--bg-card);
299	      border: 1px solid var(--border);
300	      border-radius: var(--radius-sm);
301	      font-size: 0.85rem;
302	    }
303	    .about-info-item i { color: var(--accent); width: 18px; }
304	    .about-visual {
305	      position: relative;
306	      border-radius: var(--radius);
307	      overflow: hidden;
308	      background: var(--bg-card);
309	      border: 1px solid var(--border);
310	      padding: 2rem;
311	    }
312	    .code-block {
313	      font-family: var(--mono);
314	      font-size: 0.8rem;
315	      line-height: 1.8;
316	      color: var(--text-muted);
317	    }
318	    .code-block .kw { color: #c678dd; }
319	    .code-block .fn { color: #61afef; }
320	    .code-block .str { color: #98c379; }
321	    .code-block .cm { color: #5c6370; font-style: italic; }
322	    .code-block .num { color: #d19a66; }
323	    .code-block .type { color: #e5c07b; }
324	
325	    /* ===== SERVICES ===== */
326	    .services-grid {
327	      display: grid;
328	      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
329	      gap: 1.5rem;
330	      margin-top: 3rem;
331	    }
332	    .service-card {
333	      background: var(--bg-card);
334	      border: 1px solid var(--border);
335	      border-radius: var(--radius);
336	      padding: 2rem;
337	      transition: var(--transition);
338	      position: relative;
339	      overflow: hidden;
340	    }
341	    .service-card::before {
342	      content: '';
343	      position: absolute;
344	      top: 0; left: 0;
345	      right: 0; height: 3px;
346	      background: linear-gradient(90deg, var(--accent), var(--accent3));
347	      opacity: 0;
348	      transition: var(--transition);
349	    }
350	    .service-card:hover {
351	      border-color: rgba(124, 92, 252, 0.3);
352	      transform: translateY(-4px);
353	      box-shadow: 0 12px 40px rgba(0,0,0,0.3);
354	    }
355	    .service-card:hover::before { opacity: 1; }
356	    .service-icon {
357	      width: 50px; height: 50px;
358	      border-radius: 14px;
359	      display: flex;
360	      align-items: center;
361	      justify-content: center;
362	      font-size: 1.25rem;
363	      margin-bottom: 1.25rem;
364	      background: rgba(124, 92, 252, 0.1);
365	      color: var(--accent);
366	    }
367	    .service-card h3 { font-size: 1.15rem; font-weight: 700; margin-bottom: 0.5rem; }
368	    .service-card p { font-size: 0.875rem; color: var(--text-muted); line-height: 1.7; }
369	
370	    /* ===== PORTFOLIO ===== */
371	    .portfolio-grid {
372	      display: grid;
373	      grid-template-columns: repeat(auto-fit, minmax(340px, 1fr));
374	      gap: 1.5rem;
375	      margin-top: 3rem;
376	    }
377	    .portfolio-card {
378	      display: block;
379	      color: inherit;
380	      text-decoration: none;
381	      background: var(--bg-card);
382	      border: 1px solid var(--border);
383	      border-radius: var(--radius);
384	      overflow: hidden;
385	      transition: var(--transition);
386	    }
387	    .portfolio-card:hover {
388	      transform: translateY(-4px);
389	      box-shadow: 0 12px 40px rgba(0,0,0,0.3);
390	      border-color: rgba(124, 92, 252, 0.25);
391	    }
392	    .portfolio-preview {
393	      height: 200px;
394	      background: var(--surface);
395	      display: flex;
396	      align-items: center;
397	      justify-content: center;
398	      position: relative;
399	      overflow: hidden;
400	    }
401	    .portfolio-preview .preview-icon {
402	      font-size: 3rem;
403	      opacity: 0.15;
404	    }
405	    .portfolio-preview .project-type {
406	      position: absolute;
407	      top: 1rem; right: 1rem;
408	      padding: 0.25rem 0.75rem;
409	      background: rgba(124, 92, 252, 0.15);
410	      border-radius: 100px;
411	      font-size: 0.7rem;
412	      font-weight: 600;
413	      color: var(--accent);
414	      border: 1px solid rgba(124, 92, 252, 0.2);
415	    }
416	    .portfolio-body { padding: 1.5rem; }
417	    .portfolio-body h3 { font-size: 1.05rem; font-weight: 700; margin-bottom: 0.4rem; }
418	    .portfolio-body p { font-size: 0.85rem; color: var(--text-muted); margin-bottom: 1rem; }
419	    .portfolio-tags { display: flex; gap: 0.5rem; flex-wrap: wrap; }
420	    .portfolio-tags span {
421	      padding: 0.2rem 0.6rem;
422	      background: rgba(255,255,255,0.04);
423	      border: 1px solid var(--border);
424	      border-radius: 6px;
425	      font-size: 0.7rem;
426	      color: var(--text-muted);
427	    }
428	    .portfolio-card:hover .portfolio-tags span { border-color: rgba(124, 92, 252, 0.2); }
429	
430	    /* ===== SKILLS ===== */
431	    .skills-content {
432	      display: grid;
433	      grid-template-columns: 1fr 1fr;
434	      gap: 3rem;
435	      align-items: start;
436	      margin-top: 2rem;
437	    }
438	    .skills-categories { display: flex; flex-direction: column; gap: 1.5rem; }
439	    .skill-cat h4 {
440	      font-size: 0.85rem;
441	      font-weight: 700;
442	      text-transform: uppercase;
443	      letter-spacing: 1px;
444	      color: var(--accent3);
445	      margin-bottom: 0.75rem;
446	    }
447	    .skill-chips { display: flex; flex-wrap: wrap; gap: 0.5rem; }
448	    .skill-chip {
449	      padding: 0.35rem 0.9rem;
450	      background: rgba(255,255,255,0.03);
451	      border: 1px solid var(--border);
452	      border-radius: 8px;
453	      font-size: 0.8rem;
454	      color: var(--text-muted);
455	      transition: var(--transition);
456	    }
457	    .skill-chip:hover {
458	      border-color: var(--accent);
459	      color: var(--text);
460	      background: rgba(124, 92, 252, 0.08);
461	    }
462	    .experience-timeline { display: flex; flex-direction: column; gap: 1.25rem; }
463	    .exp-item {
464	      padding: 1.25rem;
465	      background: var(--bg-card);
466	      border: 1px solid var(--border);
467	      border-radius: var(--radius-sm);
468	    }
469	    .exp-item .exp-header {
470	      display: flex;
471	      justify-content: space-between;
472	      align-items: flex-start;
473	      margin-bottom: 0.5rem;
474	    }
475	    .exp-item .exp-title { font-weight: 700; font-size: 0.95rem; }
476	    .exp-item .exp-company { color: var(--accent); font-weight: 600; font-size: 0.85rem; }
477	    .exp-item .exp-date { font-size: 0.75rem; color: var(--text-muted); white-space: nowrap; }
478	    .exp-item .exp-desc { font-size: 0.8rem; color: var(--text-muted); line-height: 1.6; }
479	
480	    /* ===== PHILOSOPHY ===== */
481	    .philosophy-section {
482	      background: linear-gradient(135deg, rgba(124, 92, 252, 0.03), rgba(6, 182, 212, 0.03));
483	      border-top: 1px solid var(--border);
484	      border-bottom: 1px solid var(--border);
485	    }
486	    .philosophy-grid {
487	      display: grid;
488	      grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
489	      gap: 2rem;
490	      margin-top: 2rem;
491	    }
492	    .philosophy-card {
493	      text-align: center;
494	      padding: 2rem 1.5rem;
495	    }
496	    .philosophy-card .icon {
497	      font-size: 2rem;
498	      margin-bottom: 1rem;
499	      color: var(--accent3);
500	    }
501	    .philosophy-card h4 { font-weight: 700; margin-bottom: 0.5rem; }
502	    .philosophy-card p { font-size: 0.85rem; color: var(--text-muted); line-height: 1.7; }
503	
504	    /* ===== CONTACT ===== */
505	    .contact-grid {
506	      display: grid;
507	      grid-template-columns: 1fr 1fr;
508	      gap: 3rem;
509	      margin-top: 2rem;
510	    }
511	    .contact-info h3 { font-size: 1.3rem; font-weight: 700; margin-bottom: 1rem; }
512	    .contact-info p { color: var(--text-muted); margin-bottom: 1.5rem; }
513	    .contact-links { display: flex; flex-direction: column; gap: 0.75rem; }
514	    .contact-link {
515	      display: flex;
516	      align-items: center;
517	      gap: 12px;
518	      padding: 0.75rem 1rem;
519	      background: var(--bg-card);
520	      border: 1px solid var(--border);
521	      border-radius: var(--radius-sm);
522	      transition: var(--transition);
523	      color: var(--text);
524	    }
525	    .contact-link:hover {
526	      border-color: rgba(124, 92, 252, 0.3);
527	      transform: translateX(4px);
528	    }
529	    .contact-link i { width: 20px; color: var(--accent); font-size: 1.1rem; }
530	    .contact-link .link-label { font-size: 0.8rem; color: var(--text-muted); }
531	    .contact-form { display: flex; flex-direction: column; gap: 1rem; }
532	    .contact-form input,
533	    .contact-form textarea {
534	      padding: 0.9rem 1.1rem;
535	      background: var(--bg-card);
536	      border: 1px solid var(--border);
537	      border-radius: var(--radius-sm);
538	      color: var(--text);
539	      font-family: var(--font);
540	      font-size: 0.9rem;
541	      transition: var(--transition);
542	      outline: none;
543	    }
544	    .contact-form input:focus,
545	    .contact-form textarea:focus { border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-glow); }
546	    .contact-form textarea { min-height: 120px; resize: vertical; }
547	    .contact-form button { align-self: flex-start; }
548	
549	    /* ===== FOOTER ===== */
550	    footer {
551	      border-top: 1px solid var(--border);
552	      text-align: center;
553	      padding: 2rem;
554	      font-size: 0.8rem;
555	      color: var(--text-muted);
556	      position: relative;
557	      z-index: 1;
558	    }
559	    footer .heart { color: #ef4444; }
560	
561	    /* ===== RESPONSIVE ===== */
562	    @media (max-width: 900px) {
563	      .about-grid { grid-template-columns: 1fr; gap: 2rem; }
564	      .skills-content { grid-template-columns: 1fr; gap: 2rem; }
565	      .contact-grid { grid-template-columns: 1fr; }
