1213	    form?.addEventListener('submit', (e) => {
1214	      e.preventDefault();
1215	      const name = form.querySelector('input[placeholder="Your Name"]').value;
1216	      const email = form.querySelector('input[placeholder="Your Email"]').value;
1217	      const subject = form.querySelectorAll('input[type="text"]')[1]?.value || 'New Project Inquiry';
1218	      const message = form.querySelector('textarea').value;
