1226	    // === Particles ===
1227	    const canvas = document.getElementById('particles-canvas');
1228	    const ctx = canvas.getContext('2d');
1229	    let particles = [];
1230	    let mouseX = -1000, mouseY = -1000;
1231	
1232	    function resizeCanvas() {
1233	      canvas.width = window.innerWidth;
1234	      canvas.height = window.innerHeight;
1235	    }
1236	    resizeCanvas();
1237	    window.addEventListener('resize', resizeCanvas);
1238	
1239	    class Particle {
1240	      constructor() {
1241	        this.x = Math.random() * canvas.width;
1242	        this.y = Math.random() * canvas.height;
1243	        this.size = Math.random() * 2 + 0.5;
1244	        this.speedX = (Math.random() - 0.5) * 0.3;
1245	        this.speedY = (Math.random() - 0.5) * 0.3;
1246	        this.opacity = Math.random() * 0.5 + 0.1;
1247	      }
1248	      update() {
1249	        this.x += this.speedX;
1250	        this.y += this.speedY;
1251	        if (this.x < 0 || this.x > canvas.width) this.speedX *= -1;
1252	        if (this.y < 0 || this.y > canvas.height) this.speedY *= -1;
1253	        // Mouse interaction
1254	        const dx = this.x - mouseX;
1255	        const dy = this.y - mouseY;
1256	        const dist = Math.sqrt(dx * dx + dy * dy);
1257	        if (dist < 120) {
1258	          this.x += dx * 0.02;
1259	          this.y += dy * 0.02;
1260	        }
1261	      }
1262	      draw() {
1263	        ctx.beginPath();
1264	        ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
1265	        ctx.fillStyle = `rgba(124, 92, 252, ${this.opacity})`;
1266	        ctx.fill();
1267	      }
1268	    }
1269	
1270	    const particleCount = Math.min(80, Math.floor(window.innerWidth / 12));
1271	    for (let i = 0; i < particleCount; i++) particles.push(new Particle());
1272	
1273	    function animateParticles() {
1274	      ctx.clearRect(0, 0, canvas.width, canvas.height);
1275	      for (let i = 0; i < particles.length; i++) {
1276	        particles[i].update();
1277	        particles[i].draw();
1278	        for (let j = i + 1; j < particles.length; j++) {
1279	          const dx = particles[i].x - particles[j].x;
1280	          const dy = particles[i].y - particles[j].y;
1281	          const dist = Math.sqrt(dx * dx + dy * dy);
1282	          if (dist < 140) {
1283	            ctx.beginPath();
1284	            ctx.moveTo(particles[i].x, particles[i].y);
1285	            ctx.lineTo(particles[j].x, particles[j].y);
1286	            ctx.strokeStyle = `rgba(124, 92, 252, ${0.06 * (1 - dist / 140)})`;
1287	            ctx.lineWidth = 0.5;
1288	            ctx.stroke();
1289	          }
1290	        }
1291	      }
1292	      requestAnimationFrame(animateParticles);
1293	    }
1294	
1295	    document.addEventListener('mousemove', (e) => {
1296	      mouseX = e.clientX;
1297	      mouseY = e.clientY;
1298	    });
1299	    document.addEventListener('touchmove', (e) => {
1300	      mouseX = e.touches[0].clientX;
1301	      mouseY = e.touches[0].clientY;
1302	    });
1303	
1304	    animateParticles();
1305	  </script>
